class EchoHandler : HttpMessageHandler
{
    protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct) =>
        Task.FromResult(new HttpResponseMessage { Content = new StringContent(request.RequestUri!.ToString()) });
}

using System.Net;

var client = new HttpClient(new StatusHandler()) { BaseAddress = new Uri("https://api.example.com/") };

var response = await client.GetAsync("orders/1");
Console.WriteLine($"{(int)response.StatusCode} {response.IsSuccessStatusCode}");

try
{
    response.EnsureSuccessStatusCode();
}
catch (HttpRequestException ex)
{
    Console.WriteLine($"caught {ex.StatusCode}");
}

try
{
    await client.GetStringAsync("orders/1");
}
catch (HttpRequestException ex)
{
    Console.WriteLine($"GetStringAsync: {(int?)ex.StatusCode}");
}

class StatusHandler : HttpMessageHandler
{
    protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct) =>
        Task.FromResult(new HttpResponseMessage(HttpStatusCode.TooManyRequests));
}

var client = new HttpClient(new SlowHandler()) { Timeout = TimeSpan.FromMilliseconds(200) };

try
{
    await client.GetAsync("https://api.example.com/slow");
    Console.WriteLine("completed");
}
catch (TaskCanceledException ex)
{
    Console.WriteLine(ex.GetType().Name);
    Console.WriteLine(ex.InnerException?.GetType().Name ?? "no inner");
}

class SlowHandler : HttpMessageHandler
{
    protected override async Task<HttpResponseMessage> SendAsync(HttpRequestMessage request, CancellationToken ct)
    {
        await Task.Delay(TimeSpan.FromSeconds(10), ct);
        return new HttpResponseMessage();
    }
}

